export const slugifyCategory = (name) => (name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
export const bundledCategoryThumbnail = (name) => BUNDLED_CATEGORY_THUMBNAILS[slugifyCategory(name)] || null;
